package com.quincaisoft.sync;import com.quincaisoft.sync.domain.DeviceProof;import org.junit.jupiter.api.Test;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;import static org.junit.jupiter.api.Assertions.*;
class DeviceProofTest {
 static String pem(KeyPair key){return "-----BEGIN PUBLIC KEY-----\n"+Base64.getEncoder().encodeToString(key.getPublic().getEncoded())+"\n-----END PUBLIC KEY-----";}
 static String sign(KeyPair key,String text)throws Exception{var s=Signature.getInstance("SHA256withRSA");s.initSign(key.getPrivate());s.update(text.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(s.sign());}
 @Test void signatureBindsScopeEpochSequenceAndPayload()throws Exception{var g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);var pair=g.generateKeyPair();var t=UUID.randomUUID();var c=UUID.randomUUID();var b=UUID.randomUUID();var d=UUID.randomUUID();var e=UUID.randomUUID();var o=UUID.randomUUID();var text=DeviceProof.recovery(t,c,b,d,e,1,o,"COMPLETED_EXCEPTION",DeviceProof.hash("{}"));var signature=sign(pair,text);DeviceProof.verify(pem(pair),text,signature);assertThrows(IllegalArgumentException.class,()->DeviceProof.verify(pem(pair),DeviceProof.recovery(t,c,b,d,e,2,o,"COMPLETED_EXCEPTION",DeviceProof.hash("{}")),signature));assertThrows(IllegalArgumentException.class,()->DeviceProof.verify(pem(pair),text+"changed",signature));}
 @Test void weakKeysAndInvalidSignatureAreRejected()throws Exception{var g=KeyPairGenerator.getInstance("RSA");g.initialize(1024);assertThrows(IllegalArgumentException.class,()->DeviceProof.key(pem(g.generateKeyPair())));assertThrows(IllegalArgumentException.class,()->DeviceProof.verify("invalid","payload","invalid"));}
 @Test void canonicalEnvelopeHasUnambiguousLineOrder(){var id=UUID.fromString("00000000-0000-0000-0000-000000000001");assertEquals("quincai-enroll-v1\n"+String.join("\n",Collections.nCopies(5,id.toString()))+"\nnonce",DeviceProof.enrollment(id,id,id,id,id,"nonce"));assertEquals("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",DeviceProof.hash(""));}
}
